async function addFile(obj) {
    /* sdd-asis-lifecycle:begin addFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let fileCheck = false;
    $("input[type=file]").each(function() {
            if ($(this).val() == null || $(this).val() === '') {
                fileCheck = true;
                return;
            }
    });
    if (fileCheck) {
        await alertE("파일추가는 첨부파일 추가 이후에 가능합니다.");
        return;
    }
    const spanCnt = $(".mt5").length;
    if (spanCnt >= 4) {
        await alertE("첨부파일은 4개까지 첨부 가능합니다.");
        return;
    }
    const tag = '<p class="mt5"><input name="attachFile[' + spanCnt + ']" type="file" style="width: 500px; height: 27px; font-size:13px;"> <input type="button" value="파일추가" onclick="addFile(this);" class="button bt2 small">&nbsp;<input type="button" value="삭제" onclick="delFile(this);" class="button bt2 small"></p>';
    $(obj).parent().after(tag);
    /* sdd-asis-lifecycle:end */
}

