/**
 * @method
 * @name scwin.checkByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.checkByte = async function (_obj) {
    /* sdd-asis-lifecycle:begin fn_CheckByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const standardByte = 4000;
    const contnByte = scwin.getByte(_obj);
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.getByte
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj
 * @returns
 * @hidden N
*/
scwin.getByte = function (_obj) {
    /* sdd-asis-lifecycle:begin fn_GetByte — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0A') {
            iCounts += 2;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.calcContn
 * @author Inswave
 * @date 2026. 09. 29
 * @param _contn _maximum
 * @returns
 * @hidden N
*/
scwin.calcContn = function (_contn, _maximum) {
    /* sdd-asis-lifecycle:begin fn_CalcContn — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
        if (escape(ch) === '%0A') {
            inc = 2;
        } else {
            if (escape(ch).length > 4) {
                inc = 2;
            } else {
                inc = 1;
            }
        }
        nbytes += inc;
        if (nbytes > _maximum) {
            break;
        }
        rContn += ch;
    }
    return rContn;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }


